  const pool=[...stats];
  for(let i=0;i<p[1]&&pool.length;i++){const k=pool.splice(Math.floor(c.random()*pool.length),1)[0];c.stage(c.t,-1,[k]);c.stage(c.a,1,[k]);}
  c.a.soulState.randomStealRound=c.round;
}

