  if(c.t.hp<=0||!c.clear(c.t))return;
  const pool=['麻痹','中毒','烧伤','冻伤','害怕','睡眠'];
  const count=Math.min(p[0],pool.length);
  for(let i=0;i<count;i++)c.ailment(c.t,pool.splice(Math.floor(c.random()*pool.length),1)[0],c.a);
}

